<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Par\Infrastructure\Driven;

use Override;
use PDO;
use Civi\Lughauth\Features\OAuth\Par\Domain\Gateway\ParRequestGateway;
use Civi\Lughauth\Features\OAuth\Par\Domain\ParRequest;

/**
 * SQL-backed implementation of the ParRequestGateway port using PDO.
 *
 * Persists PAR request aggregates in the _oauth_par_request table with the authorization
 * parameters stored as a JSON blob. On construction expired records are purged proactively
 * to prevent unbounded table growth; this is a best-effort cleanup and does not affect
 * correctness. All queries include the tenant_id column to ensure strict tenant isolation.
 * The mapRow() helper reconstructs a fully-typed ParRequest value object from a database row,
 * decoding the JSON params and normalising the nullable usedAt field.
 */
final class ParRequestSqlAdapter implements ParRequestGateway
{
    public function __construct(private readonly PDO $pdo)
    {
        $this->purgeExpired();
    }

    /**
     * Inserts a new PAR request row, serialising the authorization parameters as a JSON string.
     * used_at is explicitly stored as NULL to mark the request as unconsumed.
     */
    #[Override]
    public function store(ParRequest $request): void
    {
        $stmt = $this->pdo->prepare(
            'INSERT INTO _oauth_par_request (request_uri, tenant_id, client_id, params_json, created_at, expires_at, used_at)
             VALUES (:request_uri, :tenant_id, :client_id, :params_json, :created_at, :expires_at, NULL)'
        );
        $stmt->bindValue('request_uri', $request->requestUri, PDO::PARAM_STR);
        $stmt->bindValue('tenant_id', $request->tenant, PDO::PARAM_STR);
        $stmt->bindValue('client_id', $request->clientId, PDO::PARAM_STR);
        $stmt->bindValue('params_json', json_encode($request->params), PDO::PARAM_STR);
        $stmt->bindValue('created_at', (new \DateTimeImmutable())->format('Y-m-d H:i:s'), PDO::PARAM_STR);
        $stmt->bindValue('expires_at', $request->expiresAt->format('Y-m-d H:i:s'), PDO::PARAM_STR);
        $stmt->execute();
    }

    /**
     * Retrieves a PAR request by its URN scoped to the given tenant, returning null when not found.
     * Does not filter by expiry or usage state; those validations belong to the use case layer.
     */
    #[Override]
    public function findByUri(string $requestUri, string $tenant): ?ParRequest
    {
        $stmt = $this->pdo->prepare(
            'SELECT * FROM _oauth_par_request WHERE request_uri = :request_uri AND tenant_id = :tenant_id'
        );
        $stmt->bindValue('request_uri', $requestUri, PDO::PARAM_STR);
        $stmt->bindValue('tenant_id', $tenant, PDO::PARAM_STR);
        $stmt->execute();

        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        if ($row === false) {
            return null;
        }

        return $this->mapRow($row);
    }

    /**
     * Stamps the used_at column with the current timestamp to mark the request as consumed.
     * The tenant_id is included in the WHERE clause to prevent cross-tenant modifications.
     */
    #[Override]
    public function markUsed(string $requestUri, string $tenant): void
    {
        $stmt = $this->pdo->prepare(
            'UPDATE _oauth_par_request SET used_at = :used_at WHERE request_uri = :request_uri AND tenant_id = :tenant_id'
        );
        $stmt->bindValue('used_at', (new \DateTimeImmutable())->format('Y-m-d H:i:s'), PDO::PARAM_STR);
        $stmt->bindValue('request_uri', $requestUri, PDO::PARAM_STR);
        $stmt->bindValue('tenant_id', $tenant, PDO::PARAM_STR);
        $stmt->execute();
    }

    private function mapRow(array $row): ParRequest
    {
        $params = json_decode((string) $row['params_json'], true);
        if (!is_array($params)) {
            $params = [];
        }

        return new ParRequest(
            requestUri: (string) $row['request_uri'],
            tenant: (string) $row['tenant_id'],
            clientId: (string) $row['client_id'],
            params: $params,
            expiresAt: new \DateTimeImmutable((string) $row['expires_at']),
            usedAt: isset($row['used_at']) && $row['used_at'] !== null
                ? new \DateTimeImmutable((string) $row['used_at'])
                : null,
        );
    }

    private function purgeExpired(): void
    {
        $stmt = $this->pdo->prepare(
            'DELETE FROM _oauth_par_request WHERE expires_at < :now'
        );
        $stmt->bindValue('now', (new \DateTimeImmutable())->format('Y-m-d H:i:s'), PDO::PARAM_STR);
        $stmt->execute();
    }
}
